package cn.academy.port.skill;
import java.io.File;import java.net.*;import java.nio.file.Path;import java.util.*;
/** Cold-link reflection with all client namespaces denied. This is NOT game bootstrap/startup. */
public final class MeltdownerBeamServerLinkRegressionTest {
 private static final class ServerLoader extends URLClassLoader {int requests;ServerLoader(URL[] urls){super(urls,ClassLoader.getPlatformClassLoader());}@Override protected Class<?> loadClass(String name,boolean resolve)throws ClassNotFoundException{if(name.startsWith("net.minecraft.client.")||name.startsWith("net.neoforged.neoforge.client.")||name.startsWith("cn.academy.port.client.")){requests++;throw new ClassNotFoundException("dedicatedserver denies "+name);}return super.loadClass(name,resolve);}}
 public static void main(String[] args)throws Exception{var urls=new ArrayList<URL>();for(var p:System.getProperty("java.class.path").split(java.util.regex.Pattern.quote(File.pathSeparator)))urls.add(Path.of(p).toUri().toURL());int classes=0;try(var loader=new ServerLoader(urls.toArray(URL[]::new))){for(var simple:List.of("Meltdowner","MeltdownerSession","MineRayBasic","MineRayBasicSession","ClassicBeamRay","MeltdownerBeamSupport")){var queue=new ArrayDeque<Class<?>>();queue.add(Class.forName("cn.academy.port.skill."+simple,false,loader));while(!queue.isEmpty()){var type=queue.remove();type.getDeclaredConstructors();type.getDeclaredFields();type.getDeclaredMethods();queue.addAll(List.of(type.getDeclaredClasses()));classes++;}}var event=Class.forName("cn.academy.port.api.SkillBlockDestroyEvent",false,loader);event.getDeclaredMethods();event.getDeclaredFields();classes++;if(loader.requests!=0)throw new AssertionError("common beam classes requested clients");}System.out.println("PASS "+classes+" common beam classes coldlinked with client namespaces denied");}
}
